import { useState } from "react";
import axios from "axios";
import "./soporte.css";

export default function Soporte() {

 const [form, setForm] = useState({
  asunto: "",
  mensaje: ""
 });

 const userId = 6;

 const validar = () => {

  if (!form.asunto || !form.mensaje) {
   alert("Todos los campos son obligatorios");
   return false;
  }

  if (form.mensaje.length < 10) {
   alert("Mensaje muy corto");
   return false;
  }

  return true;
 };

 const enviarMensaje = async () => {

  if (!validar()) return;

  try {

   await axios.post("http://localhost:3000/api/soporte", {
    ...form,
    id_usuario: userId
   });

   alert("Mensaje enviado");

   setForm({
    asunto: "",
    mensaje: ""
   });

  } catch (error) {
   alert("Error al enviar");
  }
 };

 return (
  <div className="soporte-container">

   <h2>Contáctanos</h2>
   <p>Envíanos tu consulta y te responderemos pronto.</p>

   <input
    type="text"
    placeholder="Asunto"
    value={form.asunto}
    onChange={(e) =>
     setForm({ ...form, asunto: e.target.value })
    }
   />

   <textarea
    placeholder="Mensaje"
    value={form.mensaje}
    onChange={(e) =>
     setForm({ ...form, mensaje: e.target.value })
    }
   />

   <button onClick={enviarMensaje}>
    ENVIAR MENSAJE
   </button>

  </div>
 );
}
